    required this.category,
    required this.title,
    required this.summary,
    required this.content,
    required this.icon,
    required this.accent,
    this.visualAsset,
    this.level = 'Pratique',
    this.minutes = 6,
    this.featured = false,
  });

  final String category;
  final String title;
  final String summary;
  final List<String> content;
  final IconData icon;
  final int accent;
  final String? visualAsset;
  final String level;
  final int minutes;
  final bool featured;

  Color get accentColor => Color(accent);
}

